const j = $input.first().json;
const input = readInvestigationInput(j);
if (j.investigation_id != null && !isUuid(j.investigation_id)) {
  input.ok = false;
  input.error = (input.error ? input.error + ' ' : '') + 'investigation_id must be a UUID or null.';
}
return [{
  json: {
    valid: input.ok,
    error: input.error,
    ...input.ctx,
    investigation_id: j.investigation_id || null,
    alert_summary: truncate(redact(j.summary || ''), 300),
  },
}];

// Workflow 05 – Node: "RCA result (invalid input)".
const d = $input.first().json;
return [{ json: { incident_id: d.incident_id || null, valid: false, status: 'invalid_input', rca: null, stored: false, analysis_id: null, error: { kind: 'invalid_input', message: d.error } } }];

